import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createGmailClient,collectGmailMessages,explainGmailError} from './gmail-client.js';
const response=(status,data,headers={})=>new Response(JSON.stringify(data),{status,headers});
test('403速度制限は詳細を判定して休止し再試行する',async()=>{let clock=0,calls=0;const waits=[],notices=[];const api=createGmailClient({getToken:()=> 'test-token',now:()=>clock,sleep:async ms=>{waits.push(ms);clock+=ms;},onWait:(s,e)=>notices.push([s,e.reason]),fetchFn:async()=>++calls===1?response(403,{error:{errors:[{reason:'userRateLimitExceeded'}]}}):response(200,{ok:true})});assert.deepEqual(await api('profile'),{ok:true});assert.equal(calls,2);assert.deepEqual(waits,[15000]);assert.deepEqual(notices,[[15,'userRateLimitExceeded']]);});
test('通常の連続取得を850ms間隔に抑える',async()=>{let clock=0;const times=[];const api=createGmailClient({getToken:()=> 'test-token',now:()=>clock,sleep:async ms=>clock+=ms,fetchFn:async()=>{times.push(clock);return response(200,{});}});await api('profile');await api('messages');await api('messages/a');assert.deepEqual(times,[0,850,1700]);});
test('権限不足やAPI未有効化の403を速度制限として再試行しない',async()=>{for(const reason of ['insufficientPermissions','accessNotConfigured','dailyLimitExceeded']){let calls=0,auth=0;const api=createGmailClient({getToken:()=> 'test-token',onAuthError:()=>auth++,fetchFn:async()=>{calls++;return response(403,{error:{errors:[{reason}],message:'detail'} });}});await assert.rejects(api('profile'),e=>e.message.includes(reason)&&e.message.includes('detail'));assert.equal(calls,1);assert.equal(auth,reason==='insufficientPermissions'?1:0);}});
test('429のRetry-Afterを守り、再試行回数を制限する',async()=>{let clock=0,calls=0;const waits=[];const api=createGmailClient({getToken:()=> 'test-token',now:()=>clock,sleep:async ms=>{waits.push(ms);clock+=ms;},fetchFn:async()=>{calls++;return response(429,{error:{status:'RESOURCE_EXHAUSTED'}},{'Retry-After':'20'});}});await assert.rejects(api('messages'),/429/);assert.equal(calls,4);assert.deepEqual(waits,[20000,30000,60000]);});
test('401では再接続が必要と判定する',()=>{assert.equal(explainGmailError(401,{}).auth,true);assert.equal(explainGmailError(403,{}).retryable,false);});
test('全ページを処理し、既知メールを省き、10件ずつ保存する',async()=>{const saved=[],calls=[];const api=async(resource,p)=>{calls.push(resource);if(resource==='messages')return p.pageToken?{messages:[{id:'12'}]}:{messages:Array.from({length:12},(_,i)=>({id:String(i)})),nextPageToken:'next'};return {id:resource.split('/')[1]};};const count=await collectGmailMessages({api,query:'test',isKnown:id=>id==='0',decodeMessage:m=>m,commit:async rows=>saved.push(rows.map(r=>r.id))});assert.equal(count,12);assert.deepEqual(saved.map(r=>r.length),[10,1,1]);assert.equal(calls.includes('messages/0'),false);assert.equal(calls.filter(r=>r==='messages').length,2);});
test('途中の403でも取得済みを保存し、次回は未処理分から再開する',async()=>{const known=new Set(),commits=[];let fail=true;const api=async(resource)=>{if(resource==='messages')return {messages:[{id:'a'},{id:'b'},{id:'c'}]};const id=resource.split('/')[1];if(id==='c'&&fail)throw Object.assign(Error('rate limit'),{status:403});return {id};};const args={api,query:'test',isKnown:id=>known.has(id),decodeMessage:m=>m,commit:async rows=>{commits.push(rows.map(r=>r.id));for(const row of rows)known.add(row.id);}};await assert.rejects(collectGmailMessages(args),/rate limit/);assert.deepEqual(commits,[['a','b']]);fail=false;assert.equal(await collectGmailMessages(args),1);assert.deepEqual(commits,[['a','b'],['c']]);});
test('保存失敗で処理済みにせず、同じ保存を無限に繰り返さない',async()=>{let saves=0;await assert.rejects(collectGmailMessages({api:async r=>r==='messages'?{messages:[{id:'a'}]}:{id:'a'},query:'test',isKnown:()=>false,decodeMessage:m=>m,commit:async()=>{saves++;throw Error('storage failed');}}),/storage failed/);assert.equal(saves,1);});
test('削除済み404の通知は飛ばし、他の取得を続ける',async()=>{const saved=[];await collectGmailMessages({api:async r=>{if(r==='messages')return {messages:[{id:'gone'},{id:'a'}]};if(r==='messages/gone')throw Object.assign(Error('gone'),{status:404});return {id:'a'};},query:'test',isKnown:()=>false,decodeMessage:m=>m,commit:async rows=>saved.push(...rows)});assert.deepEqual(saved,[{id:'a'}]);});
